// Dựng khung bằng $TMPDIR/khung-b — bài chỉ gồm mục tiêu, khái niệm then chốt, link học ngoài (đã kiểm HTTP 200 + tiêu đề), ý chính.
// Không dùng chuỗi nội suy hay backtick; văn bản thuần được escape khi dựng HTML.
const E = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const UL = (s) => '<ul>' + s.split(' ¦ ').map((x) => '<li>' + E(x.trim()) + '</li>').join('') + '</ul>';
const LK = (a, i) => '<ul>' + a.map((x) => '<li><a href="' + x[0].replace(/&/g, '&amp;') + '" target="_blank" rel="noopener">' + E(x[1]) + '</a> — ' + E(x[2 + i]) + '</li>').join('') + '</ul>';
const H = ['<h3>🎯 Objectives</h3>', '<h3>📖 What you will learn</h3>', '<h3>🔗 Where to learn</h3>', '<h3>📌 Key points</h3>'];
const HV = ['<h3>🎯 Mục tiêu</h3>', '<h3>📖 Học gì</h3>', '<h3>🔗 Học ở đâu</h3>', '<h3>📌 Ý chính</h3>'];
const BI = (en, vi) => '<div class="ml-en">' + en + '</div>\n<div class="ml-vi">' + vi + '</div>';
const MA = 'dam311';
const L = (slug, t, oe, ov, ke, kv, pe, pv, links) => ({
  title: t[0] + '|||' + t[1], slug, type: 'DOCUMENT',
  description: 'Khung bài (chế độ khung): ' + t[1] + ' — mục tiêu, khái niệm then chốt và nguồn học ngoài.',
  content: BI(H[0] + UL(oe) + H[1] + UL(ke) + H[2] + LK(links, 0) + H[3] + UL(pe), HV[0] + UL(ov) + HV[1] + UL(kv) + HV[2] + LK(links, 1) + HV[3] + UL(pv)),
});
const C = (n, t, desc, ls) => ({ title: 'Chapter ' + n + ' — ' + t[0] + '|||Chương ' + n + ' — ' + t[1], description: desc,
  lessons: ls.map((a, i) => L(MA + '-ts-' + n + '-' + (i + 1), a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])) });
const S0 = (t, desc, ls) => ({ title: 'Section 0 — Course framework (self-authored, no FLM syllabus)|||Mục 0 — Khung môn học (tự soạn, trường chưa công bố syllabus)', description: desc,
  lessons: ls.map((a, i) => L(MA + '-ts-0-' + (i + 1), a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])) });

const YT = (id) => 'https://www.youtube.com/watch?v=' + id;
const HAN = (f) => 'http://hanj.cs.illinois.edu/bk3/bk3_slides/' + f + '.ppt';
